(() => {
 'use strict';
 const tasks=new Set();let overlay,frameDone;const saved=new Map();
 function mount(){if(overlay||!document.body)return;overlay=document.createElement('div');overlay.id='cw-live-loader';overlay.hidden=true;overlay.setAttribute('role','status');overlay.setAttribute('aria-label','Loading Color Win');overlay.innerHTML='<div class="cw-live-orbit"><span class="cw-live-orbit-guide"></span><span class="cw-live-orbit-inner"></span><img src="/assets/loading/colorwin-logo.png" alt="Color Win" decoding="async"></div>';document.body.append(overlay);}
 function paint(){mount();if(!overlay)return;overlay.hidden=tasks.size===0;document.documentElement.toggleAttribute('data-cw-loading',tasks.size>0);for(const id of ['app']){const el=document.getElementById(id);if(!el)continue;if(tasks.size){if(!saved.has(el))saved.set(el,el.inert);el.inert=true;el.setAttribute('aria-busy','true');}else{el.inert=saved.get(el)||false;el.removeAttribute('aria-busy');saved.delete(el);}}}
 function begin(){const token={};tasks.add(token);paint();let ended=false;return ()=>{if(ended)return;ended=true;tasks.delete(token);paint();};}
 const boot=begin();
 function ready(root){if(frameDone){frameDone();frameDone=null;}const frame=[...root?.querySelectorAll('iframe')||[]].find(f=>!f.closest('[hidden]'));if(frame&&frame.dataset.cwReady!=='true'){const end=begin();let done=false;const finish=()=>{if(done)return;done=true;frame.removeEventListener('load',loaded);frame.removeEventListener('error',finish);window.removeEventListener('message',message);end();};const loaded=()=>{const sourceHome=frame.getAttribute('src')?.includes('source-home/index.html')&& !frame.getAttribute('src')?.includes('AllLotteryGames');if(!sourceHome){frame.dataset.cwReady='true';finish();}};const message=e=>{if(e.source===frame.contentWindow&&e.origin===location.origin&&e.data?.type==='cw-source-request'&&e.data.action==='home-ready')finish();};frame.addEventListener('load',loaded);frame.addEventListener('error',finish);window.addEventListener('message',message);frameDone=finish;}boot();paint();}
 window.ColorWinLoader={begin,ready};document.addEventListener('DOMContentLoaded',paint,{once:true});window.addEventListener('pagehide',()=>{frameDone?.();tasks.clear();paint();});
})();